<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientClientUriAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientClientUriAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientClientUriAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getClientUri returns null on a freshly created holder.
     */
    public function testClientUriNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientClientUriAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isClientUriAssigned());
        $this->assertNull($holder->getClientUri());
    }
}
class ImplWithTrustedClientClientUriAttributeHolderUnitTest
{
    use TrustedClientClientUriAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedClientUriRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultClientUri();
    }
}
